import { MobileApp } from '../../src/mobile/MobileApp';
import type { CompanionSnapshot } from '../../src/mobile/companion';
import '@freddai/ui/styles.css';
// Synthetic 320x320 PNG served by the fake file reader; the "remote" image is a local file served by vite.
const local = '';
const remote = `${location.origin}/@fs/Users/denisduvauchelle/Documents/code/freddai/packages/app/tests/fixtures/remote-sample.png?x=1`;
const text = `Saved to /Users/denis/Desktop/hero.png

Hosted copy: ${remote}

Rendered clip: /Users/denis/Movies/sample.mp4`;
const data: CompanionSnapshot = {projects:[{id:'p',name:'Synthetic project',color:'#777',canStart:true,provider:'claude'}],threads:[{id:'t',project:'p',title:'Inline media',status:'done',updated:Date.now(),messages:[{id:'m1',role:'user',text:'Make me an image'},{id:'m2',role:'assistant',text}],canReply:true,queued:0,error:null,provider:'claude',options:{model:'sonnet',effort:'high',permission_mode:'ask'}}]};
const mp4 = `${location.origin}/@fs/Users/denisduvauchelle/Documents/code/freddai/packages/app/tests/fixtures/sample.mp4`;
let mp4Bytes: Promise<Uint8Array> | undefined;
const b64 = (u: Uint8Array) => { let s = ''; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode(...u.subarray(i, i + 0x8000)); return btoa(s); };
const read = async (href: string, offset: number, length = 192 * 1024) => {
  (window as any).readCalls = [...((window as any).readCalls ?? []), href];
  if (/\.mp4$/.test(href)) {
    (window as any).videoReads = [...((window as any).videoReads ?? []), [offset, length]];
    mp4Bytes ??= fetch(mp4).then(async r => new Uint8Array(await r.arrayBuffer()));
    const all = await mp4Bytes; const end = Math.min(all.length, offset + Math.min(length, 65536));
    return {mime:'video/mp4', size:all.length, offset, data:b64(all.subarray(offset, end)), path:'/Users/denis/Movies/sample.mp4', kind:'video' as const};
  }
  const n = atob(local).length; return {mime:'image/png', size:n, offset, data: offset ? '' : local, path:'/Users/denis/Desktop/hero.png'};
};
createRoot(document.getElementById('root')!).render(<MobileApp client={{ generatedFile: async (_thread: string, href: string, offset: number, length?: number) => read(href, offset, length),
 async snapshot(){return structuredClone(data);},
 async models(){return [];},
 async attach(file){return {id:crypto.randomUUID(),name:file.name,bytes:file.size,mime:file.type,sha256:'synthetic'};},
 async queue(){}, async action(){},
 start:async()=>'t', reply:async()=>undefined, respond:async()=>undefined,
}}/>);
